operations.body:
query Home { home { __typename continueWatching { __typename ...MediaCard } recent { __typename ...MediaCard } favorites { __typename ... on Media { ...MediaCard } ... on Playlist { ...PlaylistCard } ... on Channel { ...ChannelCard } } shelves { __typename library { __typename id title itemCount } items { __typename ...MediaCard } } channels { __typename ...ChannelCard } } }
fragment ChannelCard on Channel { __typename id title onAir favorite }
fragment MediaCard on Media { __typename id title durationMs coverUrl favorite progress { __typename positionMs durationMs watched } }
fragment PlaylistCard on Playlist { __typename id title itemCount coverUrl favorite }

query Playlist($id: ID!) { playlist(id: $id) { __typename ...PlaylistCard description items { __typename ...MediaCard } } }
fragment MediaCard on Media { __typename id title durationMs coverUrl favorite progress { __typename positionMs durationMs watched } }
fragment PlaylistCard on Playlist { __typename id title itemCount coverUrl favorite }
